async function getHealth() {
  const res = await fetch(`${API}/health`, { signal: AbortSignal.timeout(8000) });
  const data = await res.json();
  return { status: data.status, runtime: data.commit || data.sha || '?' };
}

async function main() {
  console.log(`Waiting for runtime to propagate to ${TARGET_PREFIX}...`);
