const OWNER_TOKEN = readFileSync('/tmp/owner_at', 'utf8').trim();
const API = 'https://api.ivxholding.com';
const RUN_ID = `verify-commit-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
const PROOF_FILE = 'backend/services/ivx-factory-commit-proof.ts';
const TABLE_NAME = `ivx_factory_commit_proof_${RUN_ID.replace(/[^a-z0-9]/gi, '_').toLowerCase()}`;

async function main() {
  console.log(`Run ID: ${RUN_ID}`);
  console.log(`Proof file: ${PROOF_FILE}`);
  console.log(`Table: ${TABLE_NAME}`);
  console.log('');

  const prompt = `factory: Use the IVX Factory Engine to execute a live end-to-end proof that the commit-to-GitHub gap is fixed. (1) create_module: Create a new module file at path "${PROOF_FILE}" with content:
export const IVX_FACTORY_COMMIT_PROOF_RUN_ID = '${RUN_ID}';
export const IVX_FACTORY_COMMIT_PROOF_TIMESTAMP = '${new Date().toISOString()}';
export const IVX_FACTORY_COMMIT_PROOF_PURPOSE = 'Verify commitFactoryFilesToGitHub lands factory-created files on GitHub via ownerVariablesStore fallback.';
(2) run_supabase_migration: Apply SQL migration named "${TABLE_NAME}" with SQL:
CREATE TABLE IF NOT EXISTS public.${TABLE_NAME} (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), run_id TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
Approval phrase: CONFIRM_IVX_FACTORY_MODE.`;

  console.log('=== posting factory proof to owner-ai ===');
  const res = await fetch(`${API}/api/ivx/owner-ai`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${OWNER_TOKEN}`,
    },
    body: JSON.stringify({ message: prompt }),
  });
  const text = await res.text();
  console.log(`HTTP ${res.status} (len ${text.length})`);
  if (!res.ok) {
    console.error('FAILED:', text.slice(0, 600));
    process.exit(1);
  }
  const data = JSON.parse(text);
  const exec = data.executionStatus || {};
  console.log('\n=== executionStatus ===');
  console.log('taskId:       ', exec.taskId);
  console.log('status:       ', exec.status);
  console.log('stage:        ', exec.stage);
  console.log('liveProgress: ', exec.liveProgress);
  console.log('httpStatus:   ', exec.httpStatus);
  console.log('category:     ', exec.category);

  // Extract COMMIT SHA from the answer
  const answer = data.answer || data.message || '';
  const commitMatch = answer.match(/COMMIT SHA[:\s]*([a-f0-9]{7,40})/i);
  const filesMatch = answer.match(/FILES CREATED[:\s]*([^\n]*)/i);
  const errorMatch = answer.match(/ERROR[:\s]*([^\n]*)/i);
  const finalStatusMatch = answer.match(/FINAL STATUS[:\s]*([^\n]*)/i);
  console.log('\n=== proof parsed from answer ===');
  console.log('FINAL STATUS: ', finalStatusMatch?.[1]?.trim() || 'NOT FOUND');
  console.log('FILES CREATED: ', filesMatch?.[1]?.trim() || 'NOT FOUND');
  console.log('COMMIT SHA:    ', commitMatch?.[1]?.trim() || 'NONE');
  console.log('ERROR:         ', errorMatch?.[1]?.trim() || 'NONE');

  // If a commit SHA was returned, verify it exists on GitHub
  const commitSha = commitMatch?.[1]?.trim();
  if (commitSha && commitSha !== 'NONE') {
    console.log(`\n=== verifying commit ${commitSha.slice(0, 12)} on GitHub ===`);
    const ghRes = await fetch(`https://api.github.com/repos/ibb142/rork-global-real-estate-invest/commits/${commitSha}`);
    console.log(`GitHub API HTTP ${ghRes.status}`);
    if (ghRes.ok) {
      const ghData = await ghRes.json();
      console.log(`commit sha:     ${ghData.sha}`);
      console.log(`commit message: ${(ghData.commit?.message || '').slice(0, 120)}`);
      console.log(`author:         ${ghData.commit?.author?.name}`);
      // Check if the proof file is in this commit's tree
      const filesInCommit = Array.isArray(ghData.files) ? ghData.files.map((f) => f.filename) : [];
      console.log(`files in commit: ${JSON.stringify(filesInCommit)}`);
      const fileLanded = filesInCommit.includes(PROOF_FILE);
      console.log(`\nPROOF FILE LANDED ON GITHUB: ${fileLanded ? 'YES ✅' : 'NO ❌'}`);
    }
  } else {
    console.log('\nNo commit SHA returned — the factory commit step may still be blocked.');
    console.log('Answer snippet:', answer.slice(0, 800));
  }
}

main().catch((err) => { console.error('FATAL:', err); process.exit(1); });

