import { readFileSync } from 'node:fs';

const OWNER_TOKEN = readFileSync('/tmp/owner_at', 'utf8').trim();
const API = 'https://api.ivxholding.com';
const PAYLOAD = readFileSync('/tmp/worker-diagnostics-payload.b64', 'utf8').trim();

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function commitWithRetry(path, contentB64, message, attempt = 1) {
  const body = {
    action: 'github_commit_file',
    input: { path, content: contentB64, contentEncoding: 'gzip-base64', message },
    confirm: true,
    confirmText: 'CONFIRM_IVX_GITHUB_WRITE',
  };
  const res = await fetch(`${API}/api/ivx/developer-deploy/action`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${OWNER_TOKEN}` },
    body: JSON.stringify(body),
  });
  const text = await res.text();
  console.log(`[attempt ${attempt}] HTTP ${res.status}: ${text.slice(0, 300)}`);
  if (res.ok) {
    const data = JSON.parse(text);
    return data;
  }
  if ((res.status === 503 || res.status === 502 || res.status >= 500) && attempt < 5) {
    const backoff = 5000 * attempt;
    console.log(`  → transient ${res.status}, retrying in ${backoff}ms...`);
    await sleep(backoff);
    return commitWithRetry(path, contentB64, message, attempt + 1);
  }
  throw new Error(`commit failed HTTP ${res.status}: ${text.slice(0, 300)}`);
}

async function main() {
  console.log('=== committing worker diagnostics change ===');
  const result = await commitWithRetry(
    'backend/services/ivx-senior-developer-worker.ts',
    PAYLOAD,
    'feat: factory commit diagnostics — capture stepReached/approved/commitOk/commitError in worker job result so the COMMIT SHA NONE gap is diagnosable via the job API without runtime logs',
  );
  const sha = result?.result?.commitSha || result?.commitSha;
  if (sha) console.log(`\nCOMMIT SHA: ${sha}\nGitHub URL: https://github.com/ibb142/rork-global-real-estate-invest/commit/${sha}`);
}

main().catch((err) => { console.error('FATAL:', err); process.exit(1); });

