import { readFileSync, statSync } from 'node:fs';

const OWNER_TOKEN = readFileSync('/tmp/owner_at', 'utf8').trim();
const API = 'https://api.ivxholding.com';
const APK_PATH = '/home/user/rork-app/expo/android/app/build/outputs/apk/release/app-release.apk';
const APK_KEY = 'apk/ivx-holdings-v1.4.19.apk';

async function main() {
  const fileData = readFileSync(APK_PATH);
  const fileSize = statSync(APK_PATH).size;
  console.log(`APK size: ${(fileSize / (1024 * 1024)).toFixed(1)} MB (${fileSize} bytes)`);

  console.log('\n=== Step 1: requesting presigned upload URL ===');
  const presignRes = await fetch(`${API}/api/ivx/apk/presign-upload`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${OWNER_TOKEN}` },
    body: JSON.stringify({ key: APK_KEY, confirm: true, confirmText: 'CONFIRM_IVX_APK_UPLOAD' }),
  });
  const presignText = await presignRes.text();
  console.log(`presign HTTP ${presignRes.status}: ${presignText.slice(0, 400)}`);
  if (!presignRes.ok) { console.error('PRESIGN FAILED'); process.exit(1); }
  const presign = JSON.parse(presignText);
  const uploadUrl = presign.uploadUrl || presign.url || presign.presignedUrl;
  if (!uploadUrl) { console.error('No uploadUrl in presign response.'); process.exit(1); }
  console.log(`upload URL: ${uploadUrl.slice(0, 120)}...`);

  console.log('\n=== Step 2: uploading APK to S3 ===');
  const putRes = await fetch(uploadUrl, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/vnd.android.package-archive',
      'Content-Disposition': 'attachment; filename="ivx-holdings-v1.4.19.apk"',
      'Cache-Control': 'no-cache, no-store, must-revalidate',
    },
    body: fileData,
  });
  const putBody = await putRes.text().catch(() => '');
  console.log(`PUT HTTP ${putRes.status}, etag: ${putRes.headers.get('etag')}`);
  if (!putRes.ok) { console.error(`UPLOAD FAILED: ${putBody.slice(0, 400)}`); process.exit(1); }

  console.log('\n=== Step 3: verifying public URL ===');
  const publicUrl = `https://ivxholding.com/${APK_KEY}`;
  const verifyRes = await fetch(publicUrl, { method: 'HEAD' });
  console.log(`HEAD ${publicUrl}: HTTP ${verifyRes.status}`);
  console.log(`Content-Length: ${verifyRes.headers.get('content-length')} (expected ${fileSize})`);
  console.log(`ETag: ${verifyRes.headers.get('etag')}`);
  const contentLength = Number(verifyRes.headers.get('content-length') ?? 0);
  const etag = verifyRes.headers.get('etag') ?? '';
  const match = contentLength === fileSize;
  console.log(`\n=== UPLOAD ${match ? 'VERIFIED ✅' : 'MISMATCH ❌'} ===`);
  console.log(`public URL: ${publicUrl}`);
  console.log(`size match: ${match} (got ${contentLength}, expected ${fileSize})`);
  console.log(`etag: ${etag}`);
}

main().catch((err) => { console.error('FATAL:', err); process.exit(1); });

